import random
from itertools import combinations

def has_c4_or_c3(adj, n):
    # Check for triangles or 4-cycles
    for u in range(n):
        for v in adj[u]:
            if v <= u: continue
            # Triangle: common neighbor
            if adj[u] & adj[v]:
                return True
        # 4-cycle: two distinct neighbors w1, w2 sharing another common neighbor besides u
        nbrs = list(adj[u])
        for i in range(len(nbrs)):
            for j in range(i+1, len(nbrs)):
                common = adj[nbrs[i]] & adj[nbrs[j]]
                common = common - {u}
                if common:
                    return True
    return False

def add_edge_ok(adj, u, v):
    # Would adding edge (u,v) create a C3 or C4?
    if v in adj[u]: return False
    # C3: common neighbor of u and v
    if adj[u] & adj[v]: return False
    # C4: neighbor of u at distance 2 to v via some w (u-x-w-v), i.e., some x in adj[u] has common nbr w with v (w != u)
    # Equivalent: some neighbor x of u has a neighbor that's also a neighbor of v (and that neighbor != u)
    # Which means: adj[u] and adj[v] don't share (checked), AND no x in adj[u] with x != v has neighbor in adj[v]
    for x in adj[u]:
        if x == v: continue
        if adj[x] & adj[v]:
            # adj[x] & adj[v] contains something; if it's just {u} that's fine (since u-x-u-v isn't a cycle)
            # Wait, u is in adj[x] and if u in adj[v] then that's the edge we're adding. Ignore u.
            inter = adj[x] & adj[v] - {u}
            if inter:
                return False
    return True

